local config = {
  ui_story_31900401_1_dialog_content = "Apakah Anda menyiapkan hadiah ini?",
  ui_story_31900401_2_dialog_content = "Aku tahu mereka sedikit kasar, tapi mereka akan melakukannya untuk rakyat jelata, kan?",
  ui_story_31900401_3_dialog_content = "Aksesori batu akik, kalung mutiara—bukankah semuanya sedikit berlebihan?",
  ui_story_31900401_4_dialog_content = "Semua barang murah. Produk inferior yang tidak pernah bisa diberikan kepada seorang bangsawan.",
  ui_story_31900401_5_dialog_content = "Aku lebih tertarik kenapa kau masih terpincang-pincang dengan bajingan itu.",
  ui_story_31900401_6_dialog_content = "Pernahkah Anda mendengar tentang kelompok Progress Unshackled itu, di Lumopolis Bawah?",
  ui_story_31900401_7_dialog_content = "Aku bahkan tidak begitu yakin apa arti nama itu...",
  ui_story_31900401_8_dialog_content = "Ini adalah kelompok dukungan sebaya mantan narapidana yang bertemu untuk berbagi keterampilan dan pengetahuan.",
  ui_story_31900401_9_dialog_content = "Kedengarannya seperti grup yang hebat dengan tujuan yang positif. Tapi kenapa kamu pergi?",
  ui_story_31900401_10_dialog_content = "Saya tidak akan menghadiri pertemuan umum seperti itu, jika bukan karena saya mendapat bantuan dari mereka.",
  ui_story_31900401_11_dialog_content = "Tersangka yang kami tangkap beberapa hari lalu bersembunyi di antara kelompok ini, jadi aku tidak punya pilihan selain menyusup sendiri.",
  ui_story_31900401_12_dialog_content = "Tersangka akhirnya ditangkap, berkat anggota lainnya.",
  ui_story_31900401_13_dialog_content = "Kasusnya masih disidangkan, dan saya mungkin masih membutuhkan bantuan mereka, bahkan kesaksian mereka!",
  ui_story_31900401_14_dialog_content = "Jadi, Anda harus menerima undangan mereka.",
  ui_story_31900401_15_dialog_content = "Ayolah... Memalukan bahwa salah satu peringkat tinggi saya harus membungkuk begitu rendah untuk dilihat pada pertemuan seperti itu.",
  ui_story_31900401_16_dialog_content = "Yah, saya pikir itu mengagumkan bahwa mereka bersedia mengubah cara mereka dan mengubah kehidupan baru. Kedengarannya seperti itu akan menjadi acara yang bagus.",
  ui_story_31900401_17_dialog_content = "Apakah Anda ingin pergi?",
  ui_story_31900401_18_dialog_content = "Tidak ada salahnya untuk melihat-lihat.",
  ui_story_31900401_19_dialog_content = "Hanya saja, jangan menyesal pergi.",
  ui_story_31900401_20_dialog_content = "Selamat datang! Selamat datang teman-teman!",
  ui_story_31900401_21_dialog_content = "Terima kasih atas undangannya. Tidak perlu jabat tangan.",
  ui_story_31900401_22_dialog_content = "Kita tidak hanya memiliki bangsawan bersama kita hari ini, tetapi juga Caelestite! Kami benar-benar terpesona!",
  ui_story_31900401_23_dialog_content = "(Anda pasti bermaksud mengatakan \"terpesona\"...)",
  ui_story_31900401_24_dialog_content = "Jadi Caelestite tidak punya delapan kaki? Itulah yang saya katakan kepada orang-orang ketika keluar scamming...",
  ui_story_31900401_25_dialog_content = "(Apa yang bisa Anda scamming ...?)",
  ui_story_31900401_26_dialog_content = "Apakah kedua tamu terhormat kita peduli untuk melihat hasil kerja keras anggota kita?",
  ui_story_31900401_27_dialog_content = "Apa... Apa ini?",
  ui_story_31900401_28_dialog_content = "Ini adalah karpet tenunan tangan. Dibutuhkan pekerja terampil seminggu penuh untuk menenun.",
  ui_story_31900401_29_dialog_content = "Itu mungkin hanya permadani, tapi itu sangat berharga sehingga para bangsawan dan orang Caelest tidak akan pernah bisa membuangnya begitu saja ke tanah.",
  ui_story_31900401_30_dialog_content = "Jadi disarankan untuk memajangnya di aula atau di atas perapian sebagai hiasan.",
  ui_story_31900401_31_dialog_content = "Benarkah...?",
  ui_story_31900401_32_dialog_content = "Cobalah salah satu kue buatan saya! Semua orang mengatakan perjalanan ke Lumopolis layak dilakukan hanya untuk mereka.",
  ui_story_31900401_33_dialog_content = "Saya akan mencoba satu—",
  ui_story_31900401_34_dialog_content = "Ah! Itu menyakitkan! Apakah saya mematahkan gigi?",
  ui_story_31900401_35_dialog_content = "Saya kira tidak demikian. Tidak bisakah kamu menggigitnya? Cobalah merendamnya dalam susu terlebih dahulu.",
  ui_story_31900401_36_dialog_content = "Hmm, sepertinya Caelestite memiliki gigi yang lemah. Tidak bisa... bahkan... menggigit... kue. Oke, dicatat.",
  ui_story_31900401_37_dialog_content = "Gigiku tidak lemah! Cookie masalahnya!",
  ui_story_31900401_38_dialog_content = "Dan apa, Anda membuat catatan sehingga Anda bisa menipu orang lagi?",
  ui_story_31900401_39_dialog_content = "Apa?! Siapa yang menipu orang? Kami TIDAK akan mengizinkan penjahat lagi dalam barisan kami!",
  ui_story_31900401_40_dialog_content = "TIDAK! Tidak mungkin ada penipuan yang terjadi. Tidak seperti ada uang tunai yang harus dibuat ...",
  ui_story_31900401_41_dialog_content = "Lagi pula, acar sayuran saya terkenal di grup karena rasanya yang fenomenal. Mereka semua yang saya butuhkan untuk mendukung diri saya sendiri.",
  ui_story_31900401_42_dialog_content = "Itu benar! Rasanya benar-benar fenomenal, dan sayang untuk dilewatkan. Anda hanya harus mencoba beberapa!",
  ui_story_31900401_43_dialog_content = "Oh, er... Oke.",
  ui_story_31900401_44_dialog_content = "Anda tidak makan?",
  ui_story_31900401_45_dialog_content = "Cuma baunya...",
  ui_story_31900401_46_dialog_content = "Bagus kan?",
  ui_story_31900401_47_dialog_content = "Mmm... Baunya... fantastis...",
  ui_story_31900401_48_dialog_content = "Rasanya seratus kali lebih kuat dari baunya! Ayo, masukkan!",
  ui_story_31900401_49_dialog_content = "Err... Kain gombal ini memiliki warna yang agak istimewa.",
  ui_story_31900401_50_dialog_content = "Itu syal sutra, bukan gombal! Ya ampun, Caelestite benar-benar belum melihat dunia!",
  ui_story_31900401_51_dialog_content = "Caelestite mengacaukan kain gombal dengan syal sutra... Tercatat.",
  ui_story_31900401_52_dialog_content = "Berhentilah menulis hal-hal! Apa yang akan kau lakukan dengan itu?!",
  ui_story_31900401_53_dialog_content = "Tapi, eh, apa sebenarnya syal perak itu?",
  ui_story_31900401_54_dialog_content = "Ini adalah jenis aksesori high-end, biasanya dipakai oleh kaum bangsawan.",
  ui_story_31900401_55_dialog_content = "Bukan hal yang aneh bahwa Caelestite tidak mengetahuinya, benar, Matthieu?",
  ui_story_31900401_56_dialog_content = "Ada apa, Matthieu? Anda tidak mengatakan apa-apa selama berabad-abad?",
  ui_story_31900401_57_dialog_content = "Eh, ya. Kalian terus bicara, aku hanya melihat-lihat.",
  ui_story_31900401_58_dialog_content = "Baiklah, tamu kami yang terhormat! Buat diri Anda seperti di rumah sendiri—jangan ragu untuk mengambil apa pun yang Anda sukai.",
  ui_story_31900401_59_dialog_content = "Saya pikir saya akhirnya mengerti mengapa Anda mengatakan bahwa tentang menyesal datang ...",
  ui_story_31900401_60_dialog_content = "Saya bahkan tidak akan menggunakan cravat itu untuk kain perca.",
  ui_story_31900401_61_dialog_content = "Ini benar-benar sedikit tidak berbentuk, belum lagi berkerut, dan umumnya aneh ...",
  ui_story_31900401_62_dialog_content = "Berbicara tentang yang aneh, hal yang paling aneh pasti adalah permadani itu.",
  ui_story_31900401_63_dialog_content = "Itu adalah kekacauan yang serampangan. Aku benar-benar tidak tahu harus berkata apa lagi.",
  ui_story_31900401_64_dialog_content = "Polanya seperti penangkap lalat Venus atau tanaman mengerikan lainnya!",
  ui_story_31900401_65_dialog_content = "Rupanya itu dimaksudkan untuk menjadi mawar pagi. Tumbuhan bulat pada kelopak itu sebenarnya adalah tetesan embun...",
  ui_story_31900401_66_dialog_content = "Memikirkannya saja membuat kulitku merinding!",
  ui_story_31900401_67_dialog_content = "Mereka tertipu jika mengira bisa menjual ini kepada bangsawan. Rakyat jelata yang menggelikan.",
  ui_story_31900401_68_dialog_content = "Belum lagi kue yang tidak bisa dimakan itu. Itu keras seperti batu!",
  ui_story_31900401_69_dialog_content = "Dan acar sayuran itu... Aku bisa mencium baunya bahkan di peti besi di dasar danau!",
  ui_story_31900401_70_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_31900401_71_dialog_content = "Apa katamu?",
  ui_story_31900401_72_dialog_content = "Saya sangat senang menawarkan beberapa kue kepada Anda, tapi saya tidak pernah berpikir Anda akan...",
  ui_story_31900401_73_dialog_content = "Anda dapat meremehkan stasiun kami, tetapi bukan kerja keras kami!",
  ui_story_31900401_74_dialog_content = "Bagaimana Anda mendengar?",
  ui_story_31900401_75_dialog_content = "Kamu pikir ini hanya drama? Dua langkah lagi kami tidak akan bisa mendengar kamu?",
  ui_story_31900401_76_dialog_content = "Benar-benar sekarang! Kami tidak tuli!",
  ui_story_31900401_77_dialog_content = "Aku benar-benar minta maaf...",
  ui_story_31900401_78_dialog_content = "Jadi bagaimana jika Anda mendengarnya?",
  ui_story_31900401_79_dialog_content = "Hah?!",
  ui_story_31900401_80_dialog_content = "Kerajinan tangan Anda adalah sampah. Tidak mungkin mereka akan menjual.",
  ui_story_31900401_81_dialog_content = "Baiklah, berhenti bicara...",
  ui_story_31900401_82_dialog_content = "Bahkan anjingku tidak akan berkenan memakan kue itu!",
  ui_story_31900401_83_dialog_content = "Gawat...",
  ui_story_31900401_84_dialog_content = "Anda meminta masalah! Jangan berpikir karena kau seorang bangsawan, kami hanya akan menerima ini!",
  ui_story_31900401_85_dialog_content = "Saya dulu berspesialisasi dalam menipu bangsawan bodoh!",
  ui_story_31900401_86_dialog_content = "Bisakah semua orang tolong tenang saja! Matthieu tidak mengatakan pekerjaanmu buruk, tapi itu... itu...",
  ui_story_31900401_87_dialog_content = "Eh, itu awal yang bagus, tapi bisa ditingkatkan melalui lebih banyak latihan... Jadi jika Anda...",
  ui_story_31900401_88_dialog_content = "Keluar dari sini! Anda tidak diterima lagi!",
  ui_story_31900401_89_dialog_content = "Meninggalkan! Seharusnya tidak pernah memintamu untuk datang!",
  ui_story_31900401_90_dialog_content = "Wah, kita diusir...",
  ui_story_31900401_91_dialog_content = "Apa, kamu ingin masuk kembali...?",
  ui_story_31900401_92_dialog_content = "Tentu saja tidak.",
  ui_story_31900401_93_dialog_content = "Secara pribadi, saya pikir Anda akan merasa mudah bergaul dengan rakyat jelata. Rupanya, saya salah.",
  ui_story_31900401_94_dialog_content = "Anda memprovokasi mereka. Tidak bisa hanya tutup mulut, bukan?",
  ui_story_31900401_95_dialog_content = "Kenapa mereka tidak keluar?",
  ui_story_31900401_96_dialog_content = "Apa?",
  ui_story_31900401_97_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_31900401_98_dialog_content = "Wah, apa ini?! Aku terjebak!",
  ui_story_31900401_99_dialog_content = "Hehehehehe!",
  ui_story_31900401_100_dialog_content = "Nah, itu dia. Itu tawa penjahat.",
  ui_story_31900401_101_dialog_content = "Hmm? Bagaimana bisa kita menangkap Caelestite?",
  ui_story_31900401_102_dialog_content = "Hah? Hei, bukankah kamu sedang rapat tadi?",
  ui_story_31900401_103_dialog_content = "Apakah Anda membuat jebakan ini, orang biasa?",
  ui_story_31900401_104_dialog_content = "Namanya Cudgel!",
  ui_story_31900401_105_dialog_content = "Gada... dan apa hubunganmu dengan Sekop?",
  ui_story_31900401_106_dialog_content = "Biarkan Sekop pergi!",
  ui_story_31900401_107_dialog_content = "Aha! Akhirnya kaki tangan. Saya tahu itu, sama bijak dan luar biasanya seperti saya.",
  ui_story_31900401_108_dialog_content = "Gada apa? Sekop apa? Apa yang sedang terjadi?",
  ui_story_31900401_109_dialog_content = "Shovel adalah buronan yang kutangkap tempo hari, dengan bantuan kelompok Progress Unshackled.",
  ui_story_31900401_110_dialog_content = "Saya curiga dia punya pasangan, itulah sebabnya saya datang hari ini.",
  ui_story_31900401_111_dialog_content = "Itu selalu mengapa saya sengaja melukai mereka dan diusir, jadi rekannya mungkin muncul. Dan lihatlah, dia mengambil umpannya!",
  ui_story_31900401_112_dialog_content = "*Bersiul*",
  ui_story_31900401_113_dialog_content = "Untuk apa kamu membuat suara itu?",
  ui_story_31900401_114_dialog_content = "Saya mengatakan kepada orang-orang saya untuk bersembunyi di dekatnya dan menunggu sinyal saya. Mereka akan segera datang.",
  ui_story_31900401_115_dialog_content = "Saya benar-benar tidak berharap Anda menjadi begitu di atas segalanya. Tapi sinyalmu...",
  ui_story_31900401_116_dialog_content = "Apakah mereka benar-benar menunggu?",
  ui_story_31900401_117_dialog_content = "...",
  ui_story_31900401_118_dialog_content = "...",
  ui_story_31900401_119_dialog_content = "Ahahaha! Tidak ada yang datang!",
  ui_story_31900401_120_dialog_content = "Apa yang sedang terjadi...? *Bersiul*",
  ui_story_31900401_121_dialog_content = "Jangan repot-repot. Letak tanahnya rumit di sini, banyak tempat tersesat.",
  ui_story_31900401_122_dialog_content = "Saya lahir dan besar di sekitar sini, dan bahkan saya masih tersesat sesekali. Orang luar seperti Anda lebih banyak dilakukan.",
  ui_story_31900401_123_dialog_content = "Salah perhitungan. Saya mengabaikan detail itu ...",
  ui_story_31900401_124_dialog_content = "Heehee! Kamu lepaskan Shovel, dan aku akan memastikan Caelestite tidak akan terluka. Jika tidak...",
  ui_story_31900401_125_dialog_content = "Terserah kamu. Caelestite mungkin menikmati status yang agak unik, tetapi masih memiliki peringkat yang sama dengan Anda orang biasa.",
  ui_story_31900401_126_dialog_content = "Anda ingin menggunakan dia untuk mengancam diri saya yang mulia? Silakan, tetapi Anda membuang-buang napas, orang biasa yang bodoh.",
  ui_story_31900401_127_dialog_content = "???",
  ui_story_31900401_128_dialog_content = "Apa? Bukankah ini Caelestite dari Hall of Justice?",
  ui_story_31900401_129_option_content = "Tidak ada utang tanpa kreditur",
  ui_story_31900401_130_dialog_content = "Saya jelas bukan dari Hall of Justice.",
  ui_story_31900401_131_dialog_content = "Bagaimana kalau Anda membiarkan saya pergi, dan mengambil hakim yang mulia ini sebagai gantinya?",
  ui_story_31900401_132_dialog_content = "Yah, bukannya aku tidak tertarik dengan pertukaran, hanya saja...",
  ui_story_31900401_133_option_content = "Saya tahu kepala Balai Kehakiman",
  ui_story_31900401_134_dialog_content = "Gada, bro, kamu lepaskan aku, dan aku akan membawamu ke petisi di Balai Kehakiman.",
  ui_story_31900401_135_dialog_content = "Anda benar-benar berpikir Anda bisa menipu saya untuk pergi ke sana?",
  ui_story_31900401_136_dialog_content = "Saya tidak keberatan memberi tahu Anda bahwa kunci kandang itu sudah hilang.",
  ui_story_31900401_137_dialog_content = "!!!",
  ui_story_31900401_138_dialog_content = "Jadi meskipun aku membunuhmu, aku tidak bisa mendapatkan kunci untuk membuka kandangnya.",
  ui_story_31900401_139_dialog_content = "Haha, TIDAK ADA YANG bisa membukanya selain penciptanya. Dan itu adalah Old Hammer, mati selama 20 tahun terakhir ini.",
  ui_story_31900401_140_dialog_content = "Yang Terkuat mungkin bisa membukanya. Dia adalah pemimpin dari Progress Unshackled...",
  ui_story_31900401_141_dialog_content = "Jadi maksudmu hanya...",
  ui_story_31900401_142_dialog_content = "Kue bos lebih keras dari granit! Itu menjijikkan dan tidak bisa dimakan!",
  ui_story_31900401_143_dialog_content = "Omong kosong apa yang kamu teriakkan? Kue-kue itu sangat kenyal!",
  ui_story_31900401_144_dialog_content = "Tunggu, jadi kau berpikir...",
  ui_story_31900401_145_dialog_content = "Permadani tenunan tangan itu mengerikan! Anda bisa menggantungnya di ambang pintu dan bahkan roh jahat pun tidak berani masuk!",
  ui_story_31900401_146_dialog_content = "Apa yang salah dengan permadani? Mereka hebat!",
  ui_story_31900401_147_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_31900401_148_dialog_content = "Mengapa tanah bergetar?",
  ui_story_31900401_149_dialog_content = "Awas!",
  ui_story_31900401_150_dialog_content = "Siapa bilang kue itu menjijikkan dan tidak bisa dimakan? Maju ke depan!",
  ui_story_31900401_151_dialog_content = "Siapa yang berani mengatakan permadani itu jelek? Aku akan memelintir telinga mereka!",
  ui_story_31900401_152_dialog_content = "Itu adalah Gada.",
  ui_story_31900401_153_dialog_content = "Itu adalah Gada.",
  ui_story_31900401_154_dialog_content = "!!!",
  ui_story_31900401_155_dialog_content = "Itu bukan aku! Orang-orang itu mengatakannya!",
  ui_story_31900401_156_dialog_content = "Hah? Mengapa ada kandang di sini?",
  ui_story_31900401_157_dialog_content = "Eh? Ini adalah sangkar yang dibuat Old Hammer untuk menculik anak-anak nakal kaya yang manja!",
  ui_story_31900401_158_dialog_content = "Saya tidak berpikir saya akan pernah melihat karya Old Hammer lainnya!",
  ui_story_31900401_159_dialog_content = "Apakah seseorang terjebak?!",
  ui_story_31900401_160_dialog_content = "Menculik anak-anak?!",
  ui_story_31900401_161_dialog_content = "Itu adalah Gada.",
  ui_story_31900401_162_dialog_content = "Itu adalah Gada.",
  ui_story_31900401_163_dialog_content = "Gada! Anda masih merencanakan perbuatan jahat Anda, eh?!",
  ui_story_31900401_164_dialog_content = "Sebagai Yang Terkuat, saya tidak akan pernah membiarkan penjahat berbahaya menyusup ke grup kami!",
  ui_story_31900401_165_dialog_content = "TANGKAP MEREKA!!!",
  ui_story_31900401_166_dialog_content = "Cukup. Cudgel sudah berbusa di mulutnya. Aku akan membawanya untuk diinterogasi segera.",
  ui_story_31900401_167_dialog_content = "Tolong, O Perkasa, bisakah Anda membantu saya dan membuka sangkar ini terlebih dahulu?",
  ui_story_31900401_168_dialog_content = "Bukan masalah!",
  ui_story_31900401_169_dialog_content = "Fiuh... Akhirnya keluar juga...",
  ui_story_31900401_170_dialog_content = "Bagaimana Caelestite berakhir di kandang anak?",
  ui_story_31900401_171_dialog_content = "Jangan menyoroti fakta bahwa itu dibuat untuk anak-anak...",
  ui_story_31900401_172_dialog_content = "Saya datang dengan rencana ini untuk memancing Cudgel kembali ketika saya mengetahui bahwa Shovel memiliki pasangan.",
  ui_story_31900401_173_dialog_content = "Itu sama seperti Anda, Matthieu! Luar biasa!",
  ui_story_31900401_174_dialog_content = "Berhasil memotong pembusukan sekaligus, luar biasa!",
  ui_story_31900401_175_dialog_content = "Kami berhutang padamu, kalian berdua!",
  ui_story_31900401_176_dialog_content = "Tidak ada yang lebih berterima kasih daripada Ultimate Sashimi Platter kami yang dibuat dengan penuh kasih!",
  ui_story_31900401_177_dialog_content = "Ide yang hebat! Bawa itu, cepat!",
  ui_story_31900401_178_dialog_content = "Oh, uh... Itu tidak perlu, sungguh...",
  ui_story_31900401_179_dialog_content = "Bukan apa-apa, sungguh. Tolong, anggap itu sebagai tanda penghargaan kami!",
  ui_story_31900401_180_dialog_content = "(Gurita ini masih mengeluarkan tinta... Kita mungkin diracuni...)",
  ui_story_31900401_181_dialog_content = "Hmm…",
  ui_story_31900401_182_dialog_content = "<size=30>kamu bangun, Matthieu. Temukan alasan untuk mengatakan tidak.</size>",
  ui_story_31900401_183_dialog_content = "Terima kasih banyak, semuanya. Saya akan dengan senang hati menerimanya.",
  ui_story_31900401_184_dialog_content = "Hah?!",
  ui_story_31900401_185_dialog_content = "Saya selalu mengatakan bahwa Matthieu adalah bangsawan yang paling rendah hati dan paling mudah didekati yang pernah saya temui!",
  ui_story_31900401_186_dialog_content = "Kami akan mendukungmu selamanya, Matthieu!",
  ui_story_31900401_187_dialog_content = "Tolong, Caelestite, pesan sashimi juga.",
  ui_story_31900401_188_dialog_content = "Matthieu masih belum ngemil...",
  ui_story_31900401_189_dialog_content = "Aku baru saja akan melakukannya.",
  ui_story_31900401_190_dialog_content = "Kamu benar-benar memakannya?!",
  ui_story_31900401_191_dialog_content = "Rasa yang cukup enak, sebenarnya.",
  ui_story_31900401_192_dialog_content = "Benarkah…?",
  ui_story_31900401_193_dialog_content = "Giliranmu, Caelestite.",
  ui_story_31900401_194_dialog_content = "Baik, saya akan memiliki sedikit ...",
  ui_story_31900401_195_dialog_content = "Wow! Nah, itu beberapa sifat mencurigakan yang intens!",
  ui_story_31900401_196_dialog_content = "Apa itu tadi? Apakah kamu tidak menyukainya?",
  ui_story_31900401_197_dialog_content = "Sangat... lezat...",
  ui_story_31900401_198_dialog_content = "Bagus sekali! Dalam hal ini tolong, itu semua milikmu. Bawa pulang dan nikmatilah!",
  ui_story_31900401_199_dialog_content = "Baiklah…",
  ui_story_31900401_200_dialog_content = "(Oh tidak... Apa aku benar-benar harus memakannya...?)",
  ui_story_31900601_1_dialog_content = "Ah, cuaca yang mulia.",
  ui_story_31900601_2_dialog_content = "Tampaknya bahkan awan dan hujan harus dengan rendah hati memberi jalan saat melihat wajah mulia saya yang sedang berlibur.",
  ui_story_31900601_3_dialog_content = "Dan tidak ada kerumunan yang berisik di sekitar, yang juga bagus.",
  ui_story_31900601_4_dialog_content = "...Ini tidak akan berhasil.",
  ui_story_31900601_5_dialog_content = "Yang ini baik-baik saja.",
  ui_story_31900601_6_dialog_content = "... Sepertinya masih ada sedikit gangguan suara yang tersisa di tempat ini.",
  ui_story_31900601_7_dialog_content = "Tapi aku hanya akan mendengarkan suara ombak laut dan mengabaikannya.",
  ui_story_31900601_8_dialog_content = "Hari libur yang berharga seperti ini seharusnya dihabiskan untuk merenungkan hal-hal yang berarti.",
  ui_story_31900601_9_dialog_content = "Aku tidak menyangka mencari kerang bisa menjadi begitu merepotkan... Mungkin aku harus mencoba menggali mereka dengan sekop.",
  ui_story_31900601_10_dialog_content = "<color=#e8d9bb>Scoop, scoop!</color>",
  ui_story_31900601_11_dialog_content = "...",
  ui_story_31900601_12_dialog_content = "<color=#e8d9bb>Scoop, scoop!</color>",
  ui_story_31900601_13_dialog_content = "Cukup!",
  ui_story_31900601_14_dialog_content = "PlayerName! Apa yang kamu pikirkan datang ke tempat liburan mulia saya untuk mencari kerang?!",
  ui_story_31900601_15_dialog_content = "Belumkah kamu dengar, Matthieu?",
  ui_story_31900601_16_dialog_content = "Tempat ini baru-baru ini menjadi tempat wisata utama. Mereka bahkan telah mendirikan berbagai trik hiburan di sepanjang pantai.",
  ui_story_31900601_17_dialog_content = "Mereka sedang merekrut pekerja sementara dengan segera sekarang ini, dan mereka menawarkan jumlah Nightium yang layak per hari. Serius, pekerjaan ini jauh lebih mudah daripada mengangkut komisi!",
  ui_story_31900601_18_dialog_content = "Ah, mentalitas rakyat jelata, selalu bersedia diperintah-perintah untuk kompensasi uang yang begitu sedikit.",
  ui_story_31900601_19_dialog_content = "Hei, pekerjaan adalah pekerjaan.",
  ui_story_31900601_20_dialog_content = "Tapi hei, Matthieu, kamu sudah datang jauh-jauh ke tepi laut, jadi kenapa tidak mencoba atraksi baru?",
  ui_story_31900601_21_dialog_content = "Apakah telingaku menipuku?",
  ui_story_31900601_22_dialog_content = "Apakah Anda menyarankan bahwa saya, seorang bangsawan, berdesakan dengan sekumpulan orang biasa?!",
  ui_story_31900601_23_dialog_content = "Untuk berlari dan melompat ke dalam air seangkatan dengan kera telanjang?",
  ui_story_31900601_24_dialog_content = "Pergi. Selesaikan pekerjaanmu dengan cepat dan berhenti merusak pemandangan di sini dengan omong kosongmu!",
  ui_story_31900601_25_dialog_content = "Oke, oke, aku pergi...",
  ui_story_31900601_26_dialog_content = "<color=#e8d9bb>Scoop, scoop!</color>",
  ui_story_31900601_27_dialog_content = "Oh, ini benar-benar keindahan! Pasti akan kusimpan!",
  ui_story_31900601_28_dialog_content = "...",
  ui_story_31900601_29_dialog_content = "<color=#e8d9bb>Scoop, scoop!</color>",
  ui_story_31900601_30_dialog_content = "Sungguh pola yang cantik... Kamu milikku sekarang!",
  ui_story_31900601_31_dialog_content = "... Ini tidak bisa ditahan untuk dilihat. Garis dan warna yang berantakan, beberapa bahkan dengan tepi yang rusak...",
  ui_story_31900601_32_dialog_content = "Apakah kamu benar-benar berpikir bahwa benda-benda seperti ini cantik?",
  ui_story_31900601_33_dialog_content = "A-Apakah mereka seburuk itu?",
  ui_story_31900601_34_dialog_content = "Buang mereka.",
  ui_story_31900601_35_dialog_content = "Hah? Tapi...",
  ui_story_31900601_36_dialog_content = "Buang sampah itu. Aku, dengan mata muliaku, akan memberitahu kamu apa itu \"keindahan\" sejati.",
  ui_story_31900601_37_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian...</color>",
  ui_story_31900601_38_dialog_content = "Hmm, warna yang satu ini sedikit norak, tapi masih bisa diterima, kurang lebih. Mari kita simpan.",
  ui_story_31900601_39_dialog_content = "Bagaimana ini bisa terkubur di tumpukan pasir? Ahem! Kamu, pergi gali sekarang. Biarkan aku melihatnya dengan baik.",
  ui_story_31900601_40_dialog_content = "Um... Matthieu, aku senang kamu bersedia membantu ku mencari kerang laut.",
  ui_story_31900601_41_dialog_content = "Tapi saya akan lebih berterima kasih lagi jika kamu bisa mengambilnya sendiri.",
  ui_story_31900601_42_dialog_content = "Jangan berani-berani coba!",
  ui_story_31900601_43_dialog_content = "Bos, saya telah membawa beberapa kerang kembali.",
  ui_story_31900601_44_dialog_content = "Sudah kembali? Itulah yang saya bicarakan! Baiklah, kamu anak muda, mari kita lanjutkan ke tahap berikutnya sekarang!",
  ui_story_31900601_45_dialog_content = "Hah? Masih ada tahap selanjutnya?",
  ui_story_31900601_46_dialog_content = "Jadi, \"Bos,\" bukankah Anda terkesan dengan selera estetika luar biasa saya?",
  ui_story_31900601_47_dialog_content = "Pekerjaan membabi buta kamu sudah selesai, dan sekarang kamu akhirnya bisa pergi dan melakukan sesuatu yang benar-benar berharga, bukan?",
  ui_story_31900601_48_dialog_content = "Ehem... Sebenarnya...",
  ui_story_31900601_49_dialog_content = "... Masih ada lagi?!",
  ui_story_31900601_50_dialog_content = "Ya. Ternyata, mengumpulkan kerang hanyalah persiapan untuk acara utama. Sekarang saatnya untuk bekerja sungguh-sungguh.",
  ui_story_31900601_51_dialog_content = "... Kenyataannya, bos diam-diam menjalankan proyek komisi \"Bantuan Cinta\" yang besar.",
  ui_story_31900601_52_dialog_content = "Sungguh nama yang tidak berasa!",
  ui_story_31900601_53_dialog_content = "Pada dasarnya, pekerjaanku adalah berperan sebagai orang lewat, mengganggu target cinta dan memberi tahu mereka bahwa aku tertarik pada mereka.",
  ui_story_31900601_54_dialog_content = "Kemudian, melalui penampilan yang terkoordinasi, buat klien lain itu mengusirku, mencapai efek \"pahlawan menyelamatkan hari\".",
  ui_story_31900601_55_dialog_content = "Kerang yang baru saja kita kumpulkan adalah puncak dari segalanya. Klien yang membuat pesanan akan memberikannya kepada kekasih mereka.",
  ui_story_31900601_56_dialog_content = "Itu adalah \"aid\" target kita!",
  ui_story_31900601_57_dialog_content = "Kamu berencana menggunakan kerang yang telah kumpulkan dengan tangan muliaku untuk hal yang begitu rendah?!",
  ui_story_31900601_58_dialog_content = "Ehem... Sebenarnya aku yang menggali mereka, tapi tidak apa-apa.",
  ui_story_31900601_59_dialog_content = "Sebagai rakyat biasa yang bertindak di bawah kepemimpinan dan perlindungan saya, apa yang kamu lakukan mewakili tindakan saya sendiri.",
  ui_story_31900601_60_dialog_content = "Tapi, aku pasti gila telah membuang waktuku denganmu dalam kebodohan seperti ini... Sekarang aku akan kembali menikmati liburanku!",
  ui_story_31900601_61_dialog_content = "Kamu pergi, hah...?",
  ui_story_31900601_62_dialog_content = "Sepertinya saya juga harus mulai bekerja. Tapi bagaimana caranya saya menunjukkan kepada target bahwa saya sangat \"tertarik\" kepada mereka?",
  ui_story_31900601_63_dialog_content = "(Ada seseorang yang memakai kerang tepat di depanku. Mereka tampak cukup mudah didekati. Aku akan mencobanya!)",
  ui_story_31900601_64_dialog_content = "Maaf, Nona, saya...",
  ui_story_31900601_65_dialog_content = "Apa yang salah? Apakah ada sesuatu yang bisa saya bantu?",
  ui_story_31900601_66_dialog_content = "Um, kamu, kamu...",
  ui_story_31900601_67_dialog_content = "Saya apa?",
  ui_story_31900601_68_dialog_content = "Stamina yang kamu miliki sangat hebat!",
  ui_story_31900601_69_dialog_content = "...Hah?",
  ui_story_31900601_70_dialog_content = "Maksudku, dalam cuaca yang begitu panas, berjalan tanpa alas kaki di pasir basah dan tetap menjaga kecepatan yang stabil sepanjang waktu ini!",
  ui_story_31900601_71_dialog_content = "Itu seperti, stamina tingkat tentara di sana! Kamu mungkin bisa mendaftar sekarang dan mereka akan merekrutmu dalam sekejap!",
  ui_story_31900601_72_dialog_content = "A-Apa! Apa maksudmu?!",
  ui_story_31900601_73_dialog_content = "Anda mengharapkan seorang bangsawan Lumopolis untuk mendaftar di tentara?!",
  ui_story_31900601_74_dialog_content = "Apakah kamu menghina semua dari Lumopolis?!",
  ui_story_31900601_75_dialog_content = "Tunggu, tunggu...!",
  ui_story_31900601_76_dialog_content = "(Semua ini telah berjalan sangat buruk... Batalkan misi...!)",
  ui_story_31900601_77_dialog_content = "Berhenti di sana! Jelaskan dirimu!",
  ui_story_31900601_78_dialog_content = "(Tolong aku, seseorang!)",
  ui_story_31900601_79_dialog_content = "Halo.",
  ui_story_31900601_80_dialog_content = "Matthieu!",
  ui_story_31900601_81_dialog_content = "Teman saya tadi cukup kasar kepada Anda, tapi mohon maafkan dia, dia tidak tahu apa yang dia katakan. Ini batu permata untuk repot Anda.",
  ui_story_31900601_82_dialog_content = "Oh... ini Tuan Matthieu! Dia temanmu? Mohon maaf.",
  ui_story_31900601_83_dialog_content = "Betapa beruntungnya kamu, memiliki pahlawan muda yang tampan dan murah hati untuk menyelamatkan hari ini!",
  ui_story_31900601_84_dialog_content = "Kenapa tiba-tiba aku menjadi gadis dalam kesusahan di sini?!",
  ui_story_31900601_85_dialog_content = "Ini karena kamu bahkan tidak bisa menangani masalah sekecil itu, dan kamu jelas tidak bisa membedakan antara bangsawan dan rakyat biasa.",
  ui_story_31900601_86_dialog_content = "Jadi kamu pikir kamu bisa melakukan pekerjaan itu lebih baik daripada saya, Matthieu?",
  ui_story_31900601_87_dialog_content = "Kenapa aku harus merendahkan diri untuk melakukan pekerjaan seperti ini? Seperti yang sudah aku katakan sebelumnya, seperti monyet telanjang...",
  ui_story_31900601_88_dialog_content = "Bagus!",
  ui_story_31900601_89_dialog_content = "Apa?",
  ui_story_31900601_90_dialog_content = "Saya pikir itu mungkin saja kunci dari pekerjaan ini! Alih-alih berpura-pura tertarik pada target, yang harus kita lakukan hanyalah berusaha sebisa mungkin untuk menjadi sejengkel mungkin!",
  ui_story_31900601_91_dialog_content = "Jadi, yang perlu kamu lakukan hanyalah mengungkapkan pikiran sebenarmu tentang rakyat jelata.",
  ui_story_31900601_92_dialog_content = "Bayangkan saja, seorang asing mendekatimu tanpa sebab, dan merendahkanmu dengan bahasa yang mewah dan membingungkan.",
  ui_story_31900601_93_dialog_content = "Saya tidak bisa memikirkan hal lain yang lebih menjengkelkan di dunia ini!",
  ui_story_31900601_94_dialog_content = "... Apakah kamu sadar bahwa apa yang baru saja kamu katakan bisa merupakan kejahatan menghina seorang bangsawan?",
  ui_story_31900601_95_dialog_content = "Saya bisa mengirim Anda ke Hall of Justice kapan saja.",
  ui_story_31900601_96_dialog_content = "Nah, itu sedikit berlebihan...",
  ui_story_31900601_97_dialog_content = "\"Berlebihan\"?!",
  ui_story_31900601_98_dialog_content = "Tolong, Matthieu!",
  ui_story_31900601_99_dialog_content = "Aku mohon, tunjukkan padaku gaya mulia dalam menjengkelkan tanpa usaha!",
  ui_story_31900601_100_dialog_content = "Kau pikir hanya dengan mengatakan itu, aku akan menurutimu?!",
  ui_story_31900601_101_option_content = "Ya!",
  ui_story_31900601_102_dialog_content = "Karena ini adalah permintaan tulus dari seorang teman!",
  ui_story_31900601_103_dialog_content = "Aku percaya padamu, Matthieu!",
  ui_story_31900601_104_dialog_content = "Jangan menaruh kepercayaanmu pada tempat yang tidak dapat dipercaya!",
  ui_story_31900601_105_option_content = "Jadi, kau tidak akan membantuku?",
  ui_story_31900601_106_dialog_content = "Kurasa aku akan memikirkan hal lain saja.",
  ui_story_31900601_107_dialog_content = "Apa yang mungkin bisa kamu pikirkan?",
  ui_story_31900601_108_dialog_content = "Seperti... um... eh...",
  ui_story_31900601_109_dialog_content = "...",
  ui_story_31900601_110_dialog_content = "Aku hanya akan menunjukkan ini padamu sekali saja.",
  ui_story_31900601_111_dialog_content = "Trims!",
  ui_story_31900601_112_dialog_content = "Hoi, kamu! Orang biasa di depan!",
  ui_story_31900601_113_dialog_content = "A-aku?",
  ui_story_31900601_114_dialog_content = "Ya. Anda satu-satunya yang berpakaian begitu sembarangan di dekat hotel mewah ini, bukan?",
  ui_story_31900601_115_dialog_content = "Aku tahu kalian, rakyat jelata, selalu terasing dari keanggunan dan mode, oleh karena itu aku telah dengan sabar menoleransi kerusakan visual yang kalian timpakan padaku.",
  ui_story_31900601_116_dialog_content = "Tapi kamu telah berhasil menyimpang jauh dari rasa dan estetika yang layak, ini benar-benar—",
  ui_story_31900601_117_dialog_content = "Hmm... eh...",
  ui_story_31900601_118_dialog_content = "Tunggu, Matthieu, meskipun ini bagian dari pekerjaan, bukankah ini semua sedikit terlalu banyak...?",
  ui_story_31900601_119_dialog_content = "Kamu benar! Aku ini hanyalah rakyat jelata yang rendah, kotor, dan menjijikkan! Hanya dengan hidup saja aku sudah mencemari udara!",
  ui_story_31900601_120_dialog_content = "Hanya kekasih tercintaku yang pernah menghujani saya dengan hujan hinaan yang begitu menyakitkan dan menggembirakan!",
  ui_story_31900601_121_dialog_content = "Hrgh... tolong, ejek aku lebih banyak lagi! Aku akan melakukan apa saja!",
  ui_story_31900601_122_dialog_content = "Hei, apa-apaan dengan pria ini?!",
  ui_story_31900601_123_dialog_content = "Untuk dihina dengan begitu penuh gairah... Bisakah kamu menjadi jodoh sejatiku?",
  ui_story_31900601_124_dialog_content = "Kamu di sana, jangan mendekat!",
  ui_story_31900601_125_dialog_content = "Matthieu! Setelah diperiksa lebih dekat, um, pria ini tidak memakai kerang sama sekali!",
  ui_story_31900601_126_dialog_content = "Anda seharusnya menyadari itu lebih awal, anda bodoh!",
  ui_story_31900601_127_dialog_content = "Sedang apa kalian berdua dengan pria milikku?!",
  ui_story_31900601_128_dialog_content = "Tidak, ini adalah kesalahpahaman! Tolong biarkan saya menjelaskan...",
  ui_story_31900601_129_dialog_content = "Jelaskan itu pada kunci pas-ku!",
  ui_story_31900601_130_dialog_content = "... Lari!",
  ui_story_31900601_131_dialog_content = "Seharusnya aku tidak ikut denganmu melakukan hal bodoh seperti ini!",
  ui_story_31900601_132_dialog_content = "Aku akan minta maaf nanti, tapi untuk sekarang—tunggu! Berhenti! Laut ada di depan!",
  ui_story_31900601_133_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_31900601_134_dialog_content = "...",
  ui_story_31900601_135_dialog_content = "...",
  ui_story_31900601_136_dialog_content = "Ingatkan saya.",
  ui_story_31900601_137_dialog_content = "Kali berikutnya aku bahkan memiliki sedikit rasa penasaran tentang pekerjaan seorang rakyat jelata...",
  ui_story_31900601_138_dialog_content = "Saya harus menghukum diri saya dengan tidak mandi selama dua hari.",
  ui_story_31900601_139_dialog_content = "Oke... Pfft...",
  ui_story_31900601_140_dialog_content = "Apakah kamu baru saja tertawa?",
  ui_story_31900601_141_dialog_content = "Tidak, aku... Pfft... Hahaha!",
  ui_story_31900601_142_dialog_content = "Haha, maaf... hanya saja setelah semua kekacauan ini, rasanya kita sebenarnya telah memiliki liburan yang cukup menyenangkan bersama.",
  ui_story_31900601_143_dialog_content = "... Yah, bukan berarti hal seperti itu tidak diperbolehkan.",
  ui_story_31900601_144_dialog_content = "?",
  ui_story_31900601_145_dialog_content = "Maksud saya, jika kamu bertanya dengan sejujurnya seperti sebelumnya.",
  ui_story_31900601_146_dialog_content = "Saya, seorang bangsawan, mungkin bisa meluangkan waktu untuk bersenang-senang denganmu.",
  ui_story_31900601_147_dialog_content = "Matthieu...",
  ui_story_31900601_148_dialog_content = "Karena kita sudah basah kuyup, ayo bermain-main dengan air sedikit...",
  ui_story_31900601_149_dialog_content = "Tidak sekarang.",
  ui_story_31900601_150_dialog_content = "Aku perlu mandi. Segera, tanpa penundaan—tepat pada detik ini!",
  ui_story_31900601_151_dialog_content = "Demi cinta surga, biarkan aku mandi!!!"
}
return config
